    cat > "$_CBA_PYDIR/json_util.py" <<'CBA_PY_json_util.py'
#!/usr/bin/env python3
"""Frozen JSON merge/check CLI for Claude and Junie configs."""
from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path

# Import sibling catalog when running from a real file path.
_HERE = Path(__file__).resolve().parent
if str(_HERE) not in sys.path:
    sys.path.insert(0, str(_HERE))
from catalog import (  # noqa: E402
    ALIASES,
    faster_for_profile,
    grok_slug,
    is_skip,
    junie_slug,
    load_models,
)

CLAUDE_ENV_KEYS = [
    "ANTHROPIC_AUTH_TOKEN",
    "ANTHROPIC_API_KEY",
    "ANTHROPIC_BASE_URL",
    "ANTHROPIC_MODEL",
    "ANTHROPIC_DEFAULT_HAIKU_MODEL",
    "ANTHROPIC_DEFAULT_HAIKU_MODEL_NAME",
    "ANTHROPIC_DEFAULT_HAIKU_MODEL_DESCRIPTION",
    "ANTHROPIC_DEFAULT_SONNET_MODEL",
    "ANTHROPIC_DEFAULT_SONNET_MODEL_NAME",
    "ANTHROPIC_DEFAULT_SONNET_MODEL_DESCRIPTION",
    "ANTHROPIC_DEFAULT_OPUS_MODEL",
    "ANTHROPIC_DEFAULT_OPUS_MODEL_NAME",
    "ANTHROPIC_DEFAULT_OPUS_MODEL_DESCRIPTION",
    "ANTHROPIC_DEFAULT_FABLE_MODEL",
    "ANTHROPIC_DEFAULT_FABLE_MODEL_NAME",
    "ANTHROPIC_DEFAULT_FABLE_MODEL_DESCRIPTION",
    "CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY",
    "API_TIMEOUT_MS",
    "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC",
    "DISABLE_TELEMETRY",
    "DISABLE_ERROR_REPORTING",
    "DISABLE_PROMPT_CACHING",
]

JUNIE_PROFILE_KEYS = ("baseUrl", "id", "apiType", "apiKey", "temperature", "fasterModel")


def _atomic_write(path: Path, data: str, mode: int = 0o644) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + f".tmp.{os.getpid()}")
    if tmp.exists():
        tmp.unlink()
    fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_EXCL, mode)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(data)
        os.replace(str(tmp), str(path))
    except Exception:
        try:
            os.unlink(str(tmp))
        except OSError:
            pass
        raise


def _load_json(path: Path) -> dict:
    if not path.exists():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def _dump(obj: object) -> str:
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def stable_merge_available(existing: list, completion: list[str], skip: list[str]) -> list[str]:
    alias_set = set(ALIASES)
    skip_set = set(skip)
    completion_set = set(completion)
    out: list[str] = list(ALIASES)
    seen = set(out)
    for name in existing:
        if not isinstance(name, str):
            continue
        if name in alias_set:
            continue
        if name in skip_set or is_skip(name, []):
            continue
        if name in completion_set or name not in skip_set:
            if name not in seen:
                out.append(name)
                seen.add(name)
    for name in completion:
        if name not in seen and name not in alias_set:
            out.append(name)
            seen.add(name)
    return out


def merge_claude(existing: dict, env_updates: dict, models: dict) -> dict:
    out = dict(existing) if isinstance(existing, dict) else {}
    env = dict(out.get("env") or {})
    for k, v in env_updates.items():
        env[k] = v
    out["env"] = env
    prev = out.get("availableModels") or []
    if not isinstance(prev, list):
        prev = []
    out["availableModels"] = stable_merge_available(
        prev, models.get("completion") or [], models.get("skip") or []
    )
    return out


def merge_junie_profile(existing: dict, model_id: str, base_url: str, faster: str) -> dict:
    return {
        "baseUrl": base_url,
        "id": model_id,
        "apiType": "OpenAICompletion",
        "apiKey": "ollama",
        "temperature": 0.6,
        "fasterModel": {"id": faster},
    }


def merge_junie_config(existing: dict, model: str) -> dict:
    out = dict(existing) if isinstance(existing, dict) else {}
    cur = out.get("model")
    if cur is None or (isinstance(cur, str) and cur.startswith("custom:ollama")):
        out["model"] = model
    if "model-default-locations" not in out:
        out["model-default-locations"] = True
    if "auto-update" not in out:
        out["auto-update"] = True
    return out


def check_claude(path: Path) -> int:
    data = _load_json(path)
    env = data.get("env") or {}
    base = env.get("ANTHROPIC_BASE_URL") or ""
    if base.rstrip("/").endswith("/v1"):
        print("ANTHROPIC_BASE_URL must not end with /v1", file=sys.stderr)
        return 1
    if not env.get("ANTHROPIC_AUTH_TOKEN"):
        print("ANTHROPIC_AUTH_TOKEN missing", file=sys.stderr)
        return 1
    models = data.get("availableModels") or []
    if models[:4] != list(ALIASES):
        print("availableModels must start with sonnet,haiku,opus,fable", file=sys.stderr)
        return 1
    if len(models) != len(set(models)):
        print("availableModels has duplicates", file=sys.stderr)
        return 1
    return 0


def check_junie_profile(path: Path) -> int:
    data = _load_json(path)
    for k in ("baseUrl", "id", "apiType"):
        if k not in data:
            print(f"missing {k}", file=sys.stderr)
            return 1
    if data.get("apiType") != "OpenAICompletion":
        print("apiType must be OpenAICompletion", file=sys.stderr)
        return 1
    if not str(data.get("baseUrl", "")).endswith("/v1/chat/completions"):
        print("baseUrl must end with /v1/chat/completions", file=sys.stderr)
        return 1
    return 0


def check_junie_config(path: Path) -> int:
    data = _load_json(path)
    model = data.get("model")
    if not isinstance(model, str) or not model.startswith("custom:ollama"):
        print("model must be custom:ollama*", file=sys.stderr)
        return 1
    return 0


def cmd_merge_claude(args) -> int:
    existing = _load_json(Path(args.file))
    env_updates = json.loads(Path(args.env_json).read_text(encoding="utf-8"))
    models = json.loads(Path(args.models_json).read_text(encoding="utf-8"))
    out = merge_claude(existing, env_updates, models)
    dest = Path(args.out or args.file)
    _atomic_write(dest, _dump(out), 0o644)
    return 0


def cmd_merge_junie_profile(args) -> int:
    existing = _load_json(Path(args.file)) if Path(args.file).exists() else {}
    out = merge_junie_profile(existing, args.id, args.base_url, args.faster)
    dest = Path(args.out or args.file)
    _atomic_write(dest, _dump(out), 0o644)
    return 0


def cmd_merge_junie_config(args) -> int:
    existing = _load_json(Path(args.file))
    out = merge_junie_config(existing, args.model)
    dest = Path(args.out or args.file)
    _atomic_write(dest, _dump(out), 0o644)
    return 0


def cmd_write_junie_all(args) -> int:
    tags = json.loads(Path(args.tags).read_text(encoding="utf-8"))
    cls = json.loads(Path(args.models_json).read_text(encoding="utf-8"))
    models = load_models(tags)
    from catalog import completion_models

    comp = completion_models(models)
    dest = Path(args.models_dir)
    dest.mkdir(parents=True, exist_ok=True)
    written = 0
    for name in cls.get("completion") or []:
        faster = faster_for_profile(name, args.haiku, comp)
        merge_path = dest / (junie_slug(name) + ".json")
        _atomic_write(
            merge_path,
            _dump(merge_junie_profile({}, name, args.base_url, faster)),
            0o644,
        )
        written += 1
    for fname, mid in (("ollama.json", args.primary), ("ollama-local.json", args.local)):
        faster = faster_for_profile(mid, args.haiku, comp)
        _atomic_write(
            dest / fname,
            _dump(merge_junie_profile({}, mid, args.base_url, faster)),
            0o644,
        )
        written += 1
    print(f"junie: rewrite {written} managed profiles")
    return 0


def cmd_check(args) -> int:
    path = Path(args.file)
    if args.schema == "claude":
        return check_claude(path)
    if args.schema == "junie-profile":
        return check_junie_profile(path)
    if args.schema == "junie-config":
        return check_junie_config(path)
    return 2


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(prog="json_util.py")
    sub = p.add_subparsers(dest="cmd", required=True)

    c = sub.add_parser("merge-claude")
    c.add_argument("--file", required=True)
    c.add_argument("--env-json", required=True)
    c.add_argument("--models-json", required=True)
    c.add_argument("--out")

    j = sub.add_parser("merge-junie-profile")
    j.add_argument("--file", required=True)
    j.add_argument("--id", required=True)
    j.add_argument("--base-url", required=True)
    j.add_argument("--faster", required=True)
    j.add_argument("--out")

    jc = sub.add_parser("merge-junie-config")
    jc.add_argument("--file", required=True)
    jc.add_argument("--model", required=True)
    jc.add_argument("--out")

    wj = sub.add_parser("write-junie-all")
    wj.add_argument("--models-dir", required=True)
    wj.add_argument("--tags", required=True)
    wj.add_argument("--models-json", required=True)
    wj.add_argument("--haiku", required=True)
    wj.add_argument("--primary", required=True)
    wj.add_argument("--local", required=True)
    wj.add_argument("--base-url", required=True)

    ch = sub.add_parser("check")
    ch.add_argument("--file", required=True)
    ch.add_argument("--schema", required=True, choices=("claude", "junie-profile", "junie-config"))

    args = p.parse_args(argv)
    try:
        if args.cmd == "merge-claude":
            return cmd_merge_claude(args)
        if args.cmd == "merge-junie-profile":
            return cmd_merge_junie_profile(args)
        if args.cmd == "merge-junie-config":
            return cmd_merge_junie_config(args)
        if args.cmd == "write-junie-all":
            return cmd_write_junie_all(args)
        if args.cmd == "check":
            return cmd_check(args)
    except json.JSONDecodeError as e:
        print(f"json parse error: {e}", file=sys.stderr)
        return 1
    return 2


if __name__ == "__main__":
    sys.exit(main())
CBA_PY_json_util.py
    chmod 700 "$_CBA_PYDIR/json_util.py"
    cat > "$_CBA_PYDIR/toml_upsert.py" <<'CBA_PY_toml_upsert.py'
#!/usr/bin/env python3
"""Byte-span upsert of [model.ollama-direct-*] tables. Never tomllib.dump."""
from __future__ import annotations

import argparse
import json
import os
import re
import sys
import tomllib
from pathlib import Path

HEADER_RE = re.compile(r"^\[\[?[^\]]+\]\]?\s*$")
MANAGED_RE = re.compile(r"^\[model\.ollama-direct-[A-Za-z0-9-]+\]\s*$")
KEY_RE = re.compile(r"^(\s*)(model|name|base_url|api_key)\s*=")
DEFAULT_RE = re.compile(r"^(\s*)default\s*=")


def grok_slug(name: str) -> str:
    s = name.lower()
    for ch in ":/._":
        s = s.replace(ch, "-")
    return "ollama-direct-" + s


def parse_spans(text: str) -> tuple[list[dict], list[str]]:
    if text and not text.endswith("\n"):
        text = text + "\n"
    lines = text.split("\n")
    # trailing split empty from final newline
    if lines and lines[-1] == "":
        lines = lines[:-1]
    headers = [i for i, line in enumerate(lines) if HEADER_RE.match(line)]
    spans = []
    for idx, start in enumerate(headers):
        end = headers[idx + 1] if idx + 1 < len(headers) else len(lines)
        spans.append(
            {
                "start": start,
                "end": end,
                "header": lines[start],
                "lines": lines[start:end],
            }
        )
    return spans, lines


def body_stripped(span_lines: list[str]) -> str:
    body = list(span_lines)
    while body and body[-1].strip() == "":
        body.pop()
    return "\n".join(body)


def foreign_identity(spans: list[dict]) -> list[tuple[str, int, str]]:
    counts: dict[str, int] = {}
    out = []
    for s in spans:
        h = s["header"]
        idx = counts.get(h, 0)
        counts[h] = idx + 1
        if not MANAGED_RE.match(h):
            out.append((h, idx, body_stripped(s["lines"])))
    return out


def managed_model_value(span_lines: list[str]) -> str | None:
    for line in span_lines[1:]:
        m = re.match(r'^\s*model\s*=\s*"([^"]*)"', line)
        if m:
            return m.group(1)
        m = re.match(r"^\s*model\s*=\s*'([^']*)'", line)
        if m:
            return m.group(1)
    return None


def rewrite_managed(span_lines: list[str], name: str, host: str) -> tuple[list[str], str | None]:
    """Return new lines and optional warning."""
    header = span_lines[0]
    rest = span_lines[1:]
    warn = None
    seen = {"model": False, "name": False, "base_url": False, "api_key": False, "env_key": False}
    new_rest: list[str] = []
    canon = {
        "model": f'model = "{name}"',
        "name": f'name = "{name} (Ollama direct)"',
        "base_url": f'base_url = "{host.rstrip("/")}/v1"',
    }
    for line in rest:
        if re.match(r"^\s*env_key\s*=", line):
            seen["env_key"] = True
            new_rest.append(line)
            continue
        km = KEY_RE.match(line)
        if not km:
            new_rest.append(line)
            continue
        indent, key = km.group(1), km.group(2)
        seen[key] = True
        if key == "api_key":
            val = ""
            qm = re.search(r'=\s*"([^"]*)"', line)
            if qm:
                val = qm.group(1)
            else:
                qm = re.search(r"=\s*'([^']*)'", line)
                val = qm.group(1) if qm else line.split("=", 1)[-1].strip()
            if val == "ollama":
                new_rest.append(line)
            else:
                warn = f"refusing to overwrite non-dummy api_key in {header}"
                new_rest.append(line)
            continue
        new_rest.append(f"{indent}{canon[key]}")
    insert_at = 0
    for key in ("model", "name", "base_url"):
        if not seen[key]:
            new_rest.insert(insert_at, canon[key])
            insert_at += 1
    if not seen["api_key"] and not seen["env_key"]:
        # after base_url if present
        placed = False
        out = []
        for line in new_rest:
            out.append(line)
            if re.match(r"^\s*base_url\s*=", line) and not placed:
                out.append('api_key = "ollama"')
                placed = True
        if not placed:
            out.append('api_key = "ollama"')
        new_rest = out
    # drop trailing blanks then one blank for separator handled by rebuild
    while new_rest and new_rest[-1].strip() == "":
        new_rest.pop()
    return [header] + new_rest, warn


def new_table(name: str, host: str) -> list[str]:
    base = host.rstrip("/") + "/v1"
    return [
        f"[model.{grok_slug(name)}]",
        f'model = "{name}"',
        f'name = "{name} (Ollama direct)"',
        f'base_url = "{base}"',
        'api_key = "ollama"',
    ]


def rewrite_models_default(span_lines: list[str], slug: str) -> list[str]:
    header = span_lines[0]
    rest = span_lines[1:]
    found = False
    out = []
    for line in rest:
        if DEFAULT_RE.match(line) and not found:
            indent = DEFAULT_RE.match(line).group(1)
            out.append(f'{indent}default = "{slug}"')
            found = True
        else:
            out.append(line)
    if not found:
        out = [f'default = "{slug}"'] + out
    while out and out[-1].strip() == "":
        out.pop()
    return [header] + out


def atomic_write(path: Path, data: bytes) -> None:
    tmp = path.with_name(path.name + f".tmp.{os.getpid()}")
    if tmp.exists():
        tmp.unlink()
    fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
        os.replace(str(tmp), str(path))
    except Exception:
        try:
            os.unlink(str(tmp))
        except OSError:
            pass
        raise


def rebuild(
    lines: list[str],
    spans: list[dict],
    replacements: dict[int, list[str]],
    inserts_before: int | None,
    new_spans: list[list[str]],
) -> str:
    """Rebuild file. replacements keyed by span index. new_spans inserted before inserts_before span index."""
    out: list[str] = []
    first = spans[0]["start"] if spans else len(lines)
    out.extend(lines[:first])
    for i, span in enumerate(spans):
        if inserts_before is not None and i == inserts_before:
            for ns in new_spans:
                if out and out[-1].strip() != "":
                    out.append("")
                out.extend(ns)
                out.append("")
        if i in replacements:
            block = replacements[i]
            while block and block[-1].strip() == "":
                block = block[:-1]
            out.extend(block)
            out.append("")
        else:
            out.extend(span["lines"])
    if inserts_before is None and new_spans:
        if out and out[-1].strip() != "":
            out.append("")
        for ns in new_spans:
            out.extend(ns)
            out.append("")
    # trim extra trailing blanks to a single trailing newline
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out) + "\n"


def upsert(path: Path, catalog: list[dict], host: str, prune: bool, set_default: str | None) -> int:
    raw = path.read_bytes()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        print("file is not valid UTF-8", file=sys.stderr)
        return 1
    try:
        tomllib.loads(text)
    except tomllib.TOMLDecodeError as e:
        print(f"toml parse error before edit: {e}", file=sys.stderr)
        return 1

    names = [c["name"] for c in catalog if c.get("name")]
    name_set = set(names)
    slugs = {grok_slug(n): n for n in names}

    spans, lines = parse_spans(text)
    before_id = foreign_identity(spans)

    replacements: dict[int, list[str]] = {}
    drop: set[int] = set()
    seen_slugs: set[str] = set()

    for i, span in enumerate(spans):
        h = span["header"]
        if not MANAGED_RE.match(h):
            continue
        slug = h[len("[model.") : -1].strip()
        if slug.endswith("]"):
            slug = slug[:-1]
        # header is [model.ollama-direct-foo]
        m = re.match(r"^\[model\.(ollama-direct-[A-Za-z0-9-]+)\]\s*$", h)
        if not m:
            continue
        slug = m.group(1)
        model_val = managed_model_value(span["lines"])
        if prune and (model_val is None or model_val not in name_set):
            drop.add(i)
            print(f"- [model.{slug}]")
            continue
        # rewrite if we know this slug or model
        target_name = slugs.get(slug) or (model_val if model_val in name_set else None)
        if target_name is None:
            continue
        seen_slugs.add(grok_slug(target_name))
        new_lines, warn = rewrite_managed(span["lines"], target_name, host)
        replacements[i] = new_lines
        print(f"~ [model.{slug}]")
        if warn:
            print(warn, file=sys.stderr)

    new_tables: list[list[str]] = []
    for n in names:
        slug = grok_slug(n)
        if slug in seen_slugs:
            continue
        # also skip if a span exists we didn't mark (shouldn't)
        already = any(
            re.match(rf"^\[model\.{re.escape(slug)}\]\s*$", s["header"])
            for s in spans
            if s not in []
        )
        if already and grok_slug(n) in seen_slugs:
            continue
        if any(re.match(rf"^\[model\.{re.escape(slug)}\]\s*$", s["header"]) for s in spans):
            continue
        new_tables.append(new_table(n, host))
        print(f"+ [model.{slug}]")

    models_idx = None
    for i, span in enumerate(spans):
        if span["header"].strip() == "[models]":
            models_idx = i
            break

    if set_default and models_idx is not None and models_idx not in drop:
        src = replacements.get(models_idx, spans[models_idx]["lines"])
        replacements[models_idx] = rewrite_models_default(src, set_default)

    # apply drops by skipping those span indices
    kept = []
    index_map = {}
    for i, span in enumerate(spans):
        if i in drop:
            continue
        index_map[i] = len(kept)
        kept.append(span)

    repl2 = {}
    for old_i, block in replacements.items():
        if old_i in drop:
            continue
        repl2[index_map[old_i]] = block

    insert_at = index_map[models_idx] if models_idx is not None and models_idx not in drop else None

    new_text = rebuild(lines, kept, repl2, insert_at, new_tables)

    try:
        tomllib.loads(new_text)
    except tomllib.TOMLDecodeError as e:
        print(f"toml parse error after edit: {e}", file=sys.stderr)
        return 1

    after_spans, _ = parse_spans(new_text)
    after_id = foreign_identity(after_spans)

    def normalize_expected(ident):
        if not set_default:
            return ident
        out = []
        for h, idx, body in ident:
            if h.strip() == "[models]":
                # re-apply default rewrite to expected body for comparison
                blines = body.split("\n")
                rewritten = rewrite_models_default(blines, set_default)
                out.append((h, idx, body_stripped(rewritten)))
            else:
                out.append((h, idx, body))
        return out

    expected = normalize_expected(before_id)
    # prune/drop of managed only — foreign list should match
    if expected != after_id:
        # allow [models] change only when set_default
        print("foreign-span identity check failed", file=sys.stderr)
        exp = {(h, i) for h, i, _ in expected}
        got = {(h, i) for h, i, _ in after_id}
        if exp != got:
            print(f"  headers expected {sorted(exp)} got {sorted(got)}", file=sys.stderr)
        else:
            for a, b in zip(expected, after_id):
                if a != b:
                    print(f"  body mismatch for {a[0]!r}#{a[1]}", file=sys.stderr)
                    break
        return 1

    atomic_write(path, new_text.encode("utf-8"))
    return 0


def check(path: Path, catalog: list[dict], host: str) -> int:
    text = path.read_text(encoding="utf-8")
    try:
        tomllib.loads(text)
    except tomllib.TOMLDecodeError as e:
        print(f"toml parse error: {e}", file=sys.stderr)
        return 1
    spans, _ = parse_spans(text)
    names = [c["name"] for c in catalog if c.get("name")]
    have = {}
    for s in spans:
        m = re.match(r"^\[model\.(ollama-direct-[A-Za-z0-9-]+)\]\s*$", s["header"])
        if not m:
            continue
        have[managed_model_value(s["lines"])] = s
    missing = [n for n in names if n not in have]
    if missing:
        print("missing tables: " + ", ".join(missing[:8]), file=sys.stderr)
        return 1
    want_base = host.rstrip("/") + "/v1"
    for n, s in have.items():
        if n not in names:
            continue
        joined = "\n".join(s["lines"])
        if "/v1" not in joined:
            print(f"base_url missing /v1 in {s['header']}", file=sys.stderr)
            return 1
        if "api_key" not in joined and "env_key" not in joined:
            print(f"no api_key/env_key in {s['header']}", file=sys.stderr)
            return 1
    _ = want_base
    return 0


def load_catalog(path: Path) -> list[dict]:
    data = json.loads(path.read_text(encoding="utf-8"))
    if isinstance(data, list):
        return data
    if isinstance(data, dict) and "completion" in data:
        return [{"name": n} for n in data["completion"]]
    if isinstance(data, dict) and "models" in data:
        return [{"name": m.get("name")} for m in data["models"] if m.get("name")]
    raise SystemExit("catalog must be a list of {name} or classify JSON")


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(prog="toml_upsert.py")
    sub = p.add_subparsers(dest="cmd", required=True)
    u = sub.add_parser("upsert")
    u.add_argument("--file", required=True)
    u.add_argument("--catalog", required=True)
    u.add_argument("--host", required=True)
    u.add_argument("--prune", action="store_true")
    u.add_argument("--set-default")
    c = sub.add_parser("check")
    c.add_argument("--file", required=True)
    c.add_argument("--catalog", required=True)
    c.add_argument("--host", required=True)
    args = p.parse_args(argv)
    catalog = load_catalog(Path(args.catalog))
    if args.cmd == "upsert":
        return upsert(Path(args.file), catalog, args.host, args.prune, args.set_default)
    if args.cmd == "check":
        return check(Path(args.file), catalog, args.host)
    return 2


if __name__ == "__main__":
    sys.exit(main())
CBA_PY_toml_upsert.py
    chmod 700 "$_CBA_PYDIR/toml_upsert.py"
  fi
  printf "%s\n" "$_CBA_PYDIR/$_n"
}

# --- BEGIN 00-posix.sh ---
# POSIX helpers. local is function-only.

CBA_DRY_RUN=0
CBA_VALIDATE_ONLY=0
CBA_PRUNE=0
CBA_LIVE_PROBE=0
CBA_JSON=0
CBA_STRICT=0
CBA_VERBOSE=0
CBA_PREFER_CLOUD=0
CBA_PREFER_LOCAL=0
CBA_SET_GROK_DEFAULT=0
CBA_INSTALL_JUNIE=0
CBA_TOOLS=""
CBA_OLLAMA_HOST=""
CBA_CATALOG_FILE=""
CBA_DEFAULT_MODEL=""
CBA_HAIKU_MODEL=""
CBA_SONNET_MODEL=""
CBA_OPUS_MODEL=""
CBA_FABLE_MODEL=""
CBA_JUNIE_PRIMARY=""
CBA_JUNIE_VERSION="2651.4"
CBA_WORKDIR=""

cba_log() {
  printf '%s\n' "$*" >&2
}

cba_verbose() {
  if [ "$CBA_VERBOSE" -eq 1 ]; then
    printf '%s\n' "$*" >&2
  fi
}

cba_die() {
  printf 'error: %s\n' "$*" >&2
  exit 1
}

cba_usage() {
  cat <<'EOF'
install-ollama-agent-config.sh [options]

  --help
  --dry-run                 print plan; write nothing
  --validate-only           discover + validate existing configs; write nothing
  --tools=LIST              comma list: claude,junie,grok,codex,opencode
  --ollama-host=URL         default: $OLLAMA_HOST or http://127.0.0.1:11434
  --catalog-file=PATH       use a saved /api/tags JSON
  --default-model=NAME
  --haiku-model=NAME
  --sonnet-model=NAME
  --opus-model=NAME
  --fable-model=NAME
  --junie-primary=SPEC      MODEL | cloud | local
  --prefer-cloud
  --prefer-local
  --prune                   Phase 2 after every selected adapter succeeded
  --live-probe
  --set-grok-default
  --install-junie
  --junie-version=VER       default 2651.4
  --json
  --strict
  --verbose
EOF
}

cba_parse_args() {
  while [ $# -gt 0 ]; do
    case "$1" in
      --help|-h) cba_usage; exit 0 ;;
      --dry-run) CBA_DRY_RUN=1; shift ;;
      --validate-only) CBA_VALIDATE_ONLY=1; shift ;;
      --tools=*) CBA_TOOLS=${1#--tools=}; shift ;;
      --tools) CBA_TOOLS=$2; shift 2 ;;
      --ollama-host=*) CBA_OLLAMA_HOST=${1#--ollama-host=}; shift ;;
      --ollama-host) CBA_OLLAMA_HOST=$2; shift 2 ;;
      --catalog-file=*) CBA_CATALOG_FILE=${1#--catalog-file=}; shift ;;
      --catalog-file) CBA_CATALOG_FILE=$2; shift 2 ;;
      --default-model=*) CBA_DEFAULT_MODEL=${1#--default-model=}; shift ;;
      --default-model) CBA_DEFAULT_MODEL=$2; shift 2 ;;
      --haiku-model=*) CBA_HAIKU_MODEL=${1#--haiku-model=}; shift ;;
      --haiku-model) CBA_HAIKU_MODEL=$2; shift 2 ;;
      --sonnet-model=*) CBA_SONNET_MODEL=${1#--sonnet-model=}; shift ;;
      --sonnet-model) CBA_SONNET_MODEL=$2; shift 2 ;;
      --opus-model=*) CBA_OPUS_MODEL=${1#--opus-model=}; shift ;;
      --opus-model) CBA_OPUS_MODEL=$2; shift 2 ;;
      --fable-model=*) CBA_FABLE_MODEL=${1#--fable-model=}; shift ;;
      --fable-model) CBA_FABLE_MODEL=$2; shift 2 ;;
      --junie-primary=*) CBA_JUNIE_PRIMARY=${1#--junie-primary=}; shift ;;
      --junie-primary) CBA_JUNIE_PRIMARY=$2; shift 2 ;;
      --prefer-cloud) CBA_PREFER_CLOUD=1; shift ;;
      --prefer-local) CBA_PREFER_LOCAL=1; shift ;;
      --prune) CBA_PRUNE=1; shift ;;
      --live-probe) CBA_LIVE_PROBE=1; shift ;;
      --set-grok-default) CBA_SET_GROK_DEFAULT=1; shift ;;
      --install-junie) CBA_INSTALL_JUNIE=1; shift ;;
      --junie-version=*) CBA_JUNIE_VERSION=${1#--junie-version=}; shift ;;
      --junie-version) CBA_JUNIE_VERSION=$2; shift 2 ;;
      --json) CBA_JSON=1; shift ;;
      --strict) CBA_STRICT=1; shift ;;
      --verbose) CBA_VERBOSE=1; shift ;;
      --) shift; break ;;
      -*) cba_die "unknown option: $1" ;;
      *) break ;;
    esac
  done
}

cba_need_bin() {
  if ! command -v "$1" >/dev/null 2>&1; then
    cba_die "missing $1 ($2)"
  fi
}

cba_mkwork() {
  CBA_WORKDIR=${TMPDIR:-/tmp}/cba.$$
  mkdir -p "$CBA_WORKDIR"
  chmod 700 "$CBA_WORKDIR"
}

cba_cleanup() {
  if [ -n "${CBA_WORKDIR:-}" ] && [ -d "$CBA_WORKDIR" ]; then
    rm -rf "$CBA_WORKDIR"
  fi
}

cba_py() {
  _name=$1
  shift
  if [ -n "${CBA_DIST:-}" ]; then
    _script=$(_cba_extract_py "$_name")
    python3 "$_script" "$@"
  else
    python3 "$CBA_ROOT/lib/$_name" "$@"
  fi
}

cba_host_default() {
  if [ -n "$CBA_OLLAMA_HOST" ]; then
    printf '%s\n' "$CBA_OLLAMA_HOST"
    return
  fi
  if [ -n "${CLOUDBSD_OLLAMA_HOST:-}" ]; then
    printf '%s\n' "$CLOUDBSD_OLLAMA_HOST"
    return
  fi
  if [ -n "${OLLAMA_HOST:-}" ]; then
    printf '%s\n' "$OLLAMA_HOST"
    return
  fi
  printf '%s\n' "http://127.0.0.1:11434"
}

cba_strip_slash() {
  _u=$1
  while [ "$_u" != "${_u%/}" ]; do
    _u=${_u%/}
  done
  printf '%s\n' "$_u"
}
# --- END 00-posix.sh ---

# --- BEGIN 10-linuxulator.sh ---
cba_linuxulator_ok() {
  [ "$(uname -s)" = "FreeBSD" ] || return 0
  if [ ! -d /compat/linux/proc ]; then
    cba_log "warn: /compat/linux/proc missing"
    return 1
  fi
  if ! mount | grep -q 'linprocfs on /compat/linux/proc'; then
    cba_log "warn: linprocfs not mounted on /compat/linux/proc"
    return 1
  fi
  if [ ! -x /compat/linux/lib64/ld-linux-x86-64.so.2 ]; then
    cba_log "warn: linux ld.so missing"
    return 1
  fi
  return 0
}
# --- END 10-linuxulator.sh ---

# --- BEGIN 20-discover.sh ---
cba_curl_catalog() {
  _url=$1
  _out=$2
  _hdrs=""
  if [ -n "${OLLAMA_API_KEY:-}" ]; then
    _hdrs="-H Authorization: Bearer ${OLLAMA_API_KEY}"
  fi
  # shellcheck disable=SC2086
  curl -fsS --connect-timeout 3 --max-time 15 -o "$_out" $_hdrs "$_url"
}

cba_discover() {
  CBA_HOST=$(cba_strip_slash "$(cba_host_default)")
  CBA_TAGS="$CBA_WORKDIR/tags.json"
  if [ -n "$CBA_CATALOG_FILE" ]; then
    cp "$CBA_CATALOG_FILE" "$CBA_TAGS" || cba_die "cannot read --catalog-file"
    return 0
  fi
  if cba_curl_catalog "$CBA_HOST/api/tags" "$CBA_TAGS"; then
    return 0
  fi
  if cba_curl_catalog "$CBA_HOST/v1/models" "$CBA_WORKDIR/v1models.json"; then
    python3 -c '
import json,sys
p=sys.argv[1]; o=sys.argv[2]
d=json.load(open(p))
models=[{"name": m.get("id"), "capabilities": []} for m in d.get("data",[]) if m.get("id")]
json.dump({"models": models}, open(o,"w"), indent=2)
' "$CBA_WORKDIR/v1models.json" "$CBA_TAGS"
    return 0
  fi
  if command -v ollama >/dev/null 2>&1; then
    ollama list > "$CBA_WORKDIR/ollama.list" || true
    python3 -c '
import json,sys
names=[]
for line in open(sys.argv[1]):
    if line.startswith("NAME") or not line.strip():
        continue
    names.append(line.split()[0])
json.dump({"models":[{"name":n,"capabilities":[]} for n in names]}, open(sys.argv[2],"w"), indent=2)
' "$CBA_WORKDIR/ollama.list" "$CBA_TAGS"
    return 0
  fi
  cba_die "cannot discover models from $CBA_HOST"
}
# --- END 20-discover.sh ---

# --- BEGIN 30-classify.sh ---
cba_classify() {
  CBA_CLASS="$CBA_WORKDIR/class.json"
  set -- classify --tags "$CBA_TAGS" --out "$CBA_CLASS"
  if [ "$CBA_PREFER_CLOUD" -eq 1 ]; then
    set -- "$@" --prefer-cloud
  fi
  if [ "$CBA_PREFER_LOCAL" -eq 1 ]; then
    set -- "$@" --prefer-local
  fi
  if [ -n "$CBA_HAIKU_MODEL" ]; then set -- "$@" --haiku-model "$CBA_HAIKU_MODEL"; fi
  if [ -n "$CBA_SONNET_MODEL" ]; then set -- "$@" --sonnet-model "$CBA_SONNET_MODEL"; fi
  if [ -n "$CBA_OPUS_MODEL" ]; then set -- "$@" --opus-model "$CBA_OPUS_MODEL"; fi
  if [ -n "$CBA_FABLE_MODEL" ]; then set -- "$@" --fable-model "$CBA_FABLE_MODEL"; fi
  if [ -n "$CBA_DEFAULT_MODEL" ]; then set -- "$@" --default-model "$CBA_DEFAULT_MODEL"; fi
  if [ -n "$CBA_JUNIE_PRIMARY" ]; then set -- "$@" --junie-primary "$CBA_JUNIE_PRIMARY"; fi
  cba_py catalog.py "$@" || cba_die "classify failed"
  CBA_ROLE_HAIKU=$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["roles"]["haiku"])' "$CBA_CLASS")
  CBA_ROLE_SONNET=$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["roles"]["sonnet"])' "$CBA_CLASS")
  CBA_ROLE_OPUS=$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["roles"]["opus"])' "$CBA_CLASS")
  CBA_ROLE_FABLE=$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["roles"]["fable"])' "$CBA_CLASS")
  CBA_JUNIE_PRI=$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["junie_primary"])' "$CBA_CLASS")
  CBA_JUNIE_LOC=$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["junie_local"])' "$CBA_CLASS")
  CBA_N_COMP=$(python3 -c 'import json,sys; print(len(json.load(open(sys.argv[1]))["completion"]))' "$CBA_CLASS")
  CBA_N_SKIP=$(python3 -c 'import json,sys; print(len(json.load(open(sys.argv[1]))["skip"]))' "$CBA_CLASS")
  CBA_N_TOTAL=$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["total"])' "$CBA_CLASS")
}
# --- END 30-classify.sh ---

# --- BEGIN 40-backup.sh ---
cba_stamp() {
  date +%Y%m%d-%H%M%S
}

cba_prune_old_backups() {
  _dir=$1
  _glob=$2
  _n=0
  # newest 20 kept; never delete *.broken
  ls -1t "$_dir"/$_glob 2>/dev/null | while read -r f; do
    case "$f" in
      *.broken) continue ;;
    esac
    _n=$((_n + 1))
    if [ "$_n" -gt 20 ]; then
      rm -f "$f"
    fi
  done
}

cba_backup_file() {
  _src=$1
  _destdir=$2
  _mode=${3:-644}
  [ -f "$_src" ] || return 0
  mkdir -p -m 755 "$_destdir"
  _dst="$_destdir/$(basename "$_src").$(cba_stamp)"
  if [ "$_mode" = "600" ]; then
    mkdir -p -m 700 "$_destdir"
    python3 -c '
import os,sys,shutil
src,dst=sys.argv[1],sys.argv[2]
fd=os.open(dst, os.O_WRONLY|os.O_CREAT|os.O_EXCL, 0o600)
os.close(fd)
shutil.copyfile(src,dst)
os.chmod(dst, 0o600)
' "$_src" "$_dst"
  else
    cp -p "$_src" "$_dst"
  fi
  printf '%s\n' "$_dst"
}

cba_backup_tar() {
  _srcdir=$1
  _destdir=$2
  [ -d "$_srcdir" ] || return 0
  mkdir -p "$_destdir"
  _dst="$_destdir/models.$(cba_stamp).tar"
  tar -cf "$_dst" -C "$_srcdir" . 2>/dev/null || tar -cf "$_dst" -C "$_srcdir" .
  printf '%s\n' "$_dst"
}
# --- END 40-backup.sh ---

# --- BEGIN 50-validate.sh ---
cba_endpoint_ok() {
  _host=$1
  if curl -fsS --connect-timeout 3 --max-time 15 -o /dev/null "$_host/api/tags"; then
    return 0
  fi
  curl -fsS --connect-timeout 3 --max-time 15 -o /dev/null "$_host/v1/models"
}

cba_bin_version() {
  _bin=$1
  command -v "$_bin" >/dev/null 2>&1 || return 1
  "$_bin" --version >/dev/null 2>&1 || "$_bin" -v >/dev/null 2>&1
}
# --- END 50-validate.sh ---

# --- BEGIN claude.sh ---
cba_tool_claude() {
  command -v claude >/dev/null 2>&1 && return 0
  [ -x /usr/local/libexec/claude ]
}

cba_claude_env_json() {
  python3 -c '
import json,sys
host,haiku,sonnet,opus,fable=sys.argv[1:6]
opus_name=opus.replace(":latest","")
print(json.dumps({
  "ANTHROPIC_AUTH_TOKEN":"ollama",
  "ANTHROPIC_API_KEY":"",
  "ANTHROPIC_BASE_URL":host,
  "ANTHROPIC_MODEL":sonnet,
  "ANTHROPIC_DEFAULT_HAIKU_MODEL":haiku,
  "ANTHROPIC_DEFAULT_HAIKU_MODEL_NAME":haiku,
  "ANTHROPIC_DEFAULT_HAIKU_MODEL_DESCRIPTION":"Fast local Ollama (Haiku)",
  "ANTHROPIC_DEFAULT_SONNET_MODEL":sonnet,
  "ANTHROPIC_DEFAULT_SONNET_MODEL_NAME":sonnet,
  "ANTHROPIC_DEFAULT_SONNET_MODEL_DESCRIPTION":"Local Ollama coder (Sonnet)",
  "ANTHROPIC_DEFAULT_OPUS_MODEL":opus,
  "ANTHROPIC_DEFAULT_OPUS_MODEL_NAME":opus_name,
  "ANTHROPIC_DEFAULT_OPUS_MODEL_DESCRIPTION":"Large local Ollama coder (Opus)",
  "ANTHROPIC_DEFAULT_FABLE_MODEL":fable,
  "ANTHROPIC_DEFAULT_FABLE_MODEL_NAME":fable,
  "ANTHROPIC_DEFAULT_FABLE_MODEL_DESCRIPTION":"Newest local Ollama (Fable)",
  "CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY":"1",
  "API_TIMEOUT_MS":"1200000",
  "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC":"1",
  "DISABLE_TELEMETRY":"1",
  "DISABLE_ERROR_REPORTING":"1",
  "DISABLE_PROMPT_CACHING":"1",
}))
' "$CBA_HOST" "$CBA_ROLE_HAIKU" "$CBA_ROLE_SONNET" "$CBA_ROLE_OPUS" "$CBA_ROLE_FABLE"
}

cba_claude_write() {
  _file=${CBA_CLAUDE_SETTINGS:-$HOME/.claude/settings.json}
  mkdir -p "$(dirname "$_file")"
  cba_claude_env_json > "$CBA_WORKDIR/claude-env.json"
  cba_py json_util.py merge-claude --file "$_file" --env-json "$CBA_WORKDIR/claude-env.json" --models-json "$CBA_CLASS"
}

cba_claude_validate() {
  _file=${CBA_CLAUDE_SETTINGS:-$HOME/.claude/settings.json}
  cba_py json_util.py check --file "$_file" --schema claude || return 1
  python3 -c '
import json,sys
d=json.load(open(sys.argv[1]))
comp=json.load(open(sys.argv[2]))["completion"]
am=d.get("availableModels") or []
missing=[n for n in comp if n not in am]
if missing:
    print("availableModels missing", missing[:5], file=sys.stderr)
    sys.exit(1)
skip=json.load(open(sys.argv[2]))["skip"]
bad=[n for n in am if n in skip]
if bad:
    print("availableModels has skip-class", bad, file=sys.stderr)
    sys.exit(1)
' "$_file" "$CBA_CLASS" || return 1
  if ! cba_endpoint_ok "$CBA_HOST"; then
    cba_log "warn: endpoint check failed for $CBA_HOST"
    [ "$CBA_STRICT" -eq 1 ] && return 1
  fi
  if cba_tool_claude; then
    claude --version >/dev/null 2>&1 || cba_log "warn: claude --version failed"
  elif [ "$CBA_STRICT" -eq 1 ]; then
    return 1
  fi
  return 0
}

cba_claude_backup() {
  _file=${CBA_CLAUDE_SETTINGS:-$HOME/.claude/settings.json}
  cba_backup_file "$_file" "$HOME/.claude/backups" 644
}

cba_claude_run() {
  if [ "$CBA_VALIDATE_ONLY" -eq 1 ]; then
    cba_claude_validate
    return $?
  fi
  CBA_CLAUDE_BACKUP=$(cba_claude_backup)
  cba_claude_write || return 1
  cba_claude_validate
}

cba_claude_prune() {
  return 0
}
# --- END claude.sh ---

# --- BEGIN junie.sh ---
cba_tool_junie() {
  command -v junie >/dev/null 2>&1 && return 0
  [ -x "$HOME/bin/junie" ] && return 0
  [ -x "$HOME/.local/bin/junie" ]
}

cba_junie_faster() {
  python3 -c '
import json,sys
sys.path.insert(0, sys.argv[1])
from catalog import faster_for_profile, load_models, completion_models
tags=json.load(open(sys.argv[2]))
haiku=sys.argv[3]
pid=sys.argv[4]
comp=completion_models(load_models(tags))
print(faster_for_profile(pid, haiku, comp))
' "${CBA_ROOT:-$CBA_WORKDIR}/lib" "$CBA_TAGS" "$CBA_ROLE_HAIKU" "$1"
}

cba_junie_write() {
  _root=${CBA_JUNIE_HOME:-$HOME/.junie}
  mkdir -p "$_root/models"
  _base="$CBA_HOST/v1/chat/completions"
  cba_py json_util.py merge-junie-config --file "$_root/config.json" --model custom:ollama
  cba_py json_util.py write-junie-all \
    --models-dir "$_root/models" \
    --tags "$CBA_TAGS" \
    --models-json "$CBA_CLASS" \
    --haiku "$CBA_ROLE_HAIKU" \
    --primary "$CBA_JUNIE_PRI" \
    --local "$CBA_JUNIE_LOC" \
    --base-url "$_base"
}

cba_junie_validate() {
  _root=${CBA_JUNIE_HOME:-$HOME/.junie}
  cba_py json_util.py check --file "$_root/config.json" --schema junie-config || return 1
  cba_py json_util.py check --file "$_root/models/ollama.json" --schema junie-profile || return 1
  if ! cba_endpoint_ok "$CBA_HOST"; then
    cba_log "warn: endpoint check failed"
    [ "$CBA_STRICT" -eq 1 ] && return 1
  fi
  return 0
}

cba_junie_backup() {
  _root=${CBA_JUNIE_HOME:-$HOME/.junie}
  cba_backup_file "$_root/config.json" "$_root/backups" 644 >/dev/null
  cba_backup_tar "$_root/models" "$_root/backups"
}

cba_junie_run() {
  if [ "$CBA_VALIDATE_ONLY" -eq 1 ]; then
    cba_junie_validate
    return $?
  fi
  CBA_JUNIE_BACKUP=$(cba_junie_backup)
  cba_junie_write || return 1
  cba_junie_validate
}

cba_junie_prune() {
  _root=${CBA_JUNIE_HOME:-$HOME/.junie}
  python3 -c '
import json,os,sys
cls=json.load(open(sys.argv[1]))
d=sys.argv[2]
keep=set()
from pathlib import Path
sys.path.insert(0, sys.argv[3])
from catalog import junie_slug
for n in cls["completion"]:
    keep.add(junie_slug(n)+".json")
keep.add("ollama.json")
keep.add("ollama-local.json")
for fn in os.listdir(d):
    if not fn.endswith(".json"):
        continue
    if fn in keep:
        continue
    # only delete if it looks like a managed ollama profile
    try:
        data=json.load(open(os.path.join(d,fn)))
    except Exception:
        continue
    if data.get("apiType")!="OpenAICompletion":
        continue
    if not str(data.get("baseUrl","")).endswith("/v1/chat/completions"):
        continue
    os.unlink(os.path.join(d,fn))
    print("pruned", fn, file=sys.stderr)
' "$CBA_CLASS" "$_root/models" "${CBA_ROOT:-$CBA_WORKDIR}/lib"
}
# --- END junie.sh ---

# --- BEGIN grok.sh ---
cba_tool_grok() {
  command -v grok >/dev/null 2>&1 && return 0
  command -v grok-build >/dev/null 2>&1
}

cba_grok_warn_fragment() {
  _f=$HOME/.grok/config.models.fragment.toml
  if [ -f "$_f" ]; then
    _mode=$(python3 -c 'import os,sys; print(oct(os.stat(sys.argv[1]).st_mode & 0o777))' "$_f")
    cba_log "warn: $_f exists (mode $_mode) and is not loaded by Grok; it may contain secrets. Not rewriting."
  fi
}

cba_grok_write() {
  _file=${CBA_GROK_CONFIG:-$HOME/.grok/config.toml}
  [ -f "$_file" ] || cba_die "missing $_file"
  set -- upsert --file "$_file" --catalog "$CBA_CLASS" --host "$CBA_HOST"
  if [ "$CBA_SET_GROK_DEFAULT" -eq 1 ]; then
    _slug=$(python3 -c 'import sys; sys.path.insert(0,sys.argv[1]); from catalog import grok_slug; print(grok_slug(sys.argv[2]))' "${CBA_ROOT:-$CBA_WORKDIR}/lib" "$CBA_ROLE_SONNET")
    set -- "$@" --set-default "$_slug"
  fi
  cba_py toml_upsert.py "$@"
}

cba_grok_validate() {
  _file=${CBA_GROK_CONFIG:-$HOME/.grok/config.toml}
  cba_py toml_upsert.py check --file "$_file" --catalog "$CBA_CLASS" --host "$CBA_HOST" || return 1
  if ! cba_endpoint_ok "$CBA_HOST"; then
    cba_log "warn: endpoint check failed"
    [ "$CBA_STRICT" -eq 1 ] && return 1
  fi
  return 0
}

cba_grok_backup() {
  _file=${CBA_GROK_CONFIG:-$HOME/.grok/config.toml}
  mkdir -p -m 700 "$HOME/.grok/backups"
  cba_backup_file "$_file" "$HOME/.grok/backups" 600
}

cba_grok_run() {
  cba_grok_warn_fragment
  if [ "$CBA_VALIDATE_ONLY" -eq 1 ]; then
    cba_grok_validate
    return $?
  fi
  CBA_GROK_BACKUP=$(cba_grok_backup)
  cba_grok_write || return 1
  cba_grok_validate
}

cba_grok_prune() {
  _file=${CBA_GROK_CONFIG:-$HOME/.grok/config.toml}
  cba_py toml_upsert.py upsert --file "$_file" --catalog "$CBA_CLASS" --host "$CBA_HOST" --prune
}
# --- END grok.sh ---

# pipefail is supported on this host's /bin/sh


cba_detect_tools() {
  _list=""
  if cba_tool_claude; then _list="${_list},claude"; fi
  if cba_tool_junie; then _list="${_list},junie"; fi
  if cba_tool_grok; then _list="${_list},grok"; fi
  printf '%s\n' "${_list#,}"
}

cba_has_tool() {
  _want=$1
  _ifs=$IFS
  IFS=,
  for t in $CBA_TOOLS; do
    if [ "$t" = "$_want" ]; then
      IFS=$_ifs
      return 0
    fi
  done
  IFS=$_ifs
  return 1
}

cba_run_one() {
  _name=$1
  case "$_name" in
    claude) cba_claude_run ;;
    junie) cba_junie_run ;;
    grok) cba_grok_run ;;
    *) cba_log "skip unknown tool $_name"; return 0 ;;
  esac
}

cba_prune_one() {
  _name=$1
  case "$_name" in
    claude) cba_claude_prune ;;
    junie) cba_junie_prune ;;
    grok) cba_grok_prune ;;
  esac
}

cba_main() {
  # env fallbacks if flags empty
  [ -n "$CBA_DEFAULT_MODEL" ] || CBA_DEFAULT_MODEL=${CLOUDBSD_DEFAULT_MODEL:-}
  [ -n "$CBA_HAIKU_MODEL" ] || CBA_HAIKU_MODEL=${CLOUDBSD_HAIKU_MODEL:-}
  [ -n "$CBA_SONNET_MODEL" ] || CBA_SONNET_MODEL=${CLOUDBSD_SONNET_MODEL:-}
  [ -n "$CBA_OPUS_MODEL" ] || CBA_OPUS_MODEL=${CLOUDBSD_OPUS_MODEL:-}
  [ -n "$CBA_FABLE_MODEL" ] || CBA_FABLE_MODEL=${CLOUDBSD_FABLE_MODEL:-}

  cba_need_bin python3 "pkg install python3"
  cba_need_bin curl "pkg install curl"
  cba_mkwork
  trap cba_cleanup EXIT INT TERM

  cba_discover
  cba_classify

  if [ -z "$CBA_TOOLS" ]; then
    CBA_TOOLS=$(cba_detect_tools)
  fi
  if [ -z "$CBA_TOOLS" ]; then
    cba_die "no tools detected (claude/junie/grok). Pass --tools="
  fi

  if [ "$(uname -s)" = "FreeBSD" ]; then
    if cba_has_tool claude || cba_has_tool junie; then
      if ! cba_linuxulator_ok; then
        if [ "$CBA_STRICT" -eq 1 ]; then
          cba_die "Linuxulator check failed"
        fi
      fi
    fi
  fi

  cba_log "host: $CBA_HOST"
  cba_log "catalog: $CBA_N_TOTAL total, $CBA_N_COMP completion, $CBA_N_SKIP skip"
  cba_log "roles: haiku=$CBA_ROLE_HAIKU sonnet=$CBA_ROLE_SONNET opus=$CBA_ROLE_OPUS fable=$CBA_ROLE_FABLE"
  cba_log "junie primary=$CBA_JUNIE_PRI local=$CBA_JUNIE_LOC"
  cba_log "tools: $CBA_TOOLS"

  if [ "$CBA_DRY_RUN" -eq 1 ]; then
    cba_log "dry-run: no files written"
    exit 0
  fi

  _ok=1
  _ifs=$IFS
  IFS=,
  for t in $CBA_TOOLS; do
    IFS=$_ifs
    cba_log "adapter: $t"
    if ! cba_run_one "$t"; then
      cba_log "adapter $t failed"
      _ok=0
      break
    fi
    IFS=,
  done
  IFS=$_ifs

  if [ "$_ok" -eq 1 ] && [ "$CBA_PRUNE" -eq 1 ] && [ "$CBA_VALIDATE_ONLY" -eq 0 ]; then
    IFS=,
    for t in $CBA_TOOLS; do
      IFS=$_ifs
      cba_log "prune: $t"
      cba_prune_one "$t" || _ok=0
      IFS=,
    done
    IFS=$_ifs
  fi

  if [ "$CBA_JSON" -eq 1 ]; then
    python3 -c '
import json,sys
print(json.dumps({
  "ok": sys.argv[1]=="1",
  "host": sys.argv[2],
  "catalog": {"total": int(sys.argv[3]), "completion": int(sys.argv[4]), "skip": int(sys.argv[5])},
  "roles": {"haiku": sys.argv[6], "sonnet": sys.argv[7], "opus": sys.argv[8], "fable": sys.argv[9]},
  "tools": sys.argv[10],
}, indent=2))
' "$_ok" "$CBA_HOST" "$CBA_N_TOTAL" "$CBA_N_COMP" "$CBA_N_SKIP" \
      "$CBA_ROLE_HAIKU" "$CBA_ROLE_SONNET" "$CBA_ROLE_OPUS" "$CBA_ROLE_FABLE" "$CBA_TOOLS"
  fi

  [ "$_ok" -eq 1 ]
}

cba_parse_args "$@"
cba_main
